"""Validate the completed paired JMH matrix and reproduce its result tables."""

import argparse
import json
import re
from pathlib import Path


EXPECTED = {
    "property-named-1": ("PROPERTY_FILTER", "NAMED", "1", "32", "countPaths"),
    "property-named-64": ("PROPERTY_FILTER", "NAMED", "64", "32", "countPaths"),
    "property-named-256": ("PROPERTY_FILTER", "NAMED", "256", "32", "countPaths"),
    "property-merged-64": ("PROPERTY_FILTER", "MERGED", "64", "32", "countPaths"),
    "topology-merged-64": ("TOPOLOGY", "MERGED", "64", "32", "countPaths"),
    "topology-named-64": ("TOPOLOGY", "NAMED", "64", "32", "countPaths"),
    "topology-merged-fanout128": ("TOPOLOGY", "MERGED", "1", "128", "countPaths"),
    "label-named-64": ("LABEL", "NAMED", "64", "32", "countPaths"),
    "next-union-named-64": ("NEXT_UNION", "NAMED", "64", "32", "countPaths"),
    "prepare-property-named-64": ("PROPERTY_FILTER", "NAMED", "64", "32", "prepareAndCountPaths"),
}


def read_trial(directory, case, variant):
    stem = f"{case}-{variant}"
    records = json.loads((directory / (stem + ".json")).read_text())
    if len(records) != 1:
        raise ValueError(f"Expected one result in {stem}")
    record = records[0]
    expected_settings = {
        "mode": "avgt", "threads": 1, "forks": 2,
        "warmupIterations": 10, "warmupTime": "2 s",
        "measurementIterations": 5, "measurementTime": "2 s",
    }
    for name, value in expected_settings.items():
        if record[name] != value:
            raise ValueError(f"Unexpected {name} in {stem}: {record[name]}")
    metric = record["primaryMetric"]
    allocation = record["secondaryMetrics"]["gc.alloc.rate.norm"]
    if metric["scoreUnit"] != "us/op" or allocation["scoreUnit"] != "B/op":
        raise ValueError(f"Unexpected metric units in {stem}")
    if len(metric["rawData"]) != 2 or any(len(fork) != 5 for fork in metric["rawData"]):
        raise ValueError(f"Incomplete measurement iterations in {stem}")
    counters = []
    for line in (directory / (stem + ".full.log")).read_text().splitlines():
        if "GQL_ADJACENCY " not in line:
            continue
        values = dict(re.findall(r"(\w+)=(\S+)", line.split("GQL_ADJACENCY ", 1)[1]))
        counters.append({name: int(values[name]) for name in
                         ("evaluations", "lookupHits", "kernelViews", "plannerStatsHits")})
    if len(counters) != 2 or any(c["evaluations"] <= 0 for c in counters):
        raise ValueError(f"Missing per-fork engagement counters in {stem}")
    evaluations = sum(c["evaluations"] for c in counters)
    normalized = {name: sum(c[name] for c in counters) / evaluations for name in
                  ("lookupHits", "kernelViews", "plannerStatsHits")}
    return {
        "benchmark": record["benchmark"], "params": record["params"],
        "latency_us": {key: metric[key] for key in ("score", "scoreError", "scoreConfidence", "rawData")},
        "allocation_bytes": {key: allocation[key] for key in ("score", "scoreError", "scoreConfidence")},
        "fork_counters": counters, "counters_per_evaluation": normalized,
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--input", type=Path, default=Path(__file__).resolve().parent / "results")
    parser.add_argument("--output", type=Path, default=Path(__file__).resolve().parent)
    args = parser.parse_args()
    commands = json.loads((args.input / "commands.json").read_text())
    cases = list(dict.fromkeys(command["case"] for command in commands))
    if len(commands) != 20 or set(cases) != set(EXPECTED) or any(c["exit_code"] for c in commands):
        raise ValueError("Expected ten completed successful before/after pairs")
    expected_pairs = {(case, variant) for case in EXPECTED for variant in ("before", "after")}
    if {(command["case"], command["variant"]) for command in commands} != expected_pairs:
        raise ValueError("Expected exactly one command for each case and variant")
    results = []
    for case in cases:
        before, after = (read_trial(args.input, case, variant) for variant in ("before", "after"))
        if before["params"] != after["params"] or before["benchmark"] != after["benchmark"]:
            raise ValueError(f"Mismatched fixture or benchmark for {case}")
        params = before["params"]
        fixture = tuple(params[key] for key in ("workload", "graph", "rootCount", "fanout"))
        if fixture + (before["benchmark"].rsplit(".", 1)[1],) != EXPECTED[case]:
            raise ValueError(f"Unexpected fixture or method for {case}")
        if any(params[k] != v for k, v in
               {"language": "GQL", "adjacency": "PREFER", "nativeEvaluation": "true"}.items()):
            raise ValueError(f"Unexpected execution route for {case}")
        latency_before, latency_after = before["latency_us"], after["latency_us"]
        low_before, high_before = latency_before["scoreConfidence"]
        low_after, high_after = latency_after["scoreConfidence"]
        interval_result = ("After faster; intervals separate" if high_after < low_before else
                           "After slower; intervals separate" if high_before < low_after else
                           "Intervals overlap")
        fanout, roots = int(params["fanout"]), int(params["rootCount"])
        expected_count = fanout * fanout
        statements = roots * (fanout + fanout * fanout)
        if params["workload"] == "PROPERTY_FILTER":
            expected_count = fanout * (fanout - fanout // 2)
            statements += roots * fanout
        elif params["workload"] == "NEXT_UNION":
            expected_count *= 2
        elif params["workload"] == "LABEL":
            statements += roots * (1 + fanout) + fanout
        results.append({
            "case": case, "expected_count": expected_count, "fixture_statements": statements,
            "before": before, "after": after,
            "latency_ratio_before_over_after": latency_before["score"] / latency_after["score"],
            "latency_interval_comparison": interval_result,
            "allocation_change_percent": 100 * (after["allocation_bytes"]["score"] /
                                                 before["allocation_bytes"]["score"] - 1),
        })
    args.output.mkdir(parents=True, exist_ok=True)
    summary = {"confidence_level": 0.999, "allocation_unit": "bytes per operation",
               "counter_scope": "warmup plus measurement; setup diagnostics excluded", "cases": results}
    (args.output / "summary.json").write_text(json.dumps(summary, indent=2) + "\n")
    lines = ["# Complete paired benchmark results", "",
             "Latency is the JMH mean ± its reported 99.9% confidence-interval half-width. "
             "Ratios divide the two means; no confidence interval for a ratio is asserted. "
             "An overlap is treated as inconclusive. Allocation uses decimal MB (1,000,000 bytes).", "",
             "| Case | Before ms/op | After ms/op | Before / after | Latency interpretation |",
             "| --- | ---: | ---: | ---: | --- |"]
    for result in results:
        b, a = (result[v]["latency_us"] for v in ("before", "after"))
        lines.append(f"| {result['case']} | {b['score']/1000:.3f} ± {b['scoreError']/1000:.3f} | "
                     f"{a['score']/1000:.3f} ± {a['scoreError']/1000:.3f} | "
                     f"{result['latency_ratio_before_over_after']:.2f}× | {result['latency_interval_comparison']} |")
    lines += ["", "## Allocation and fixture sizes", "",
              "| Case | Statements | Expected count | Before MB/op | After MB/op | Allocation change |",
              "| --- | ---: | ---: | ---: | ---: | ---: |"]
    for result in results:
        b, a = (result[v]["allocation_bytes"]["score"] / 1e6 for v in ("before", "after"))
        lines.append(f"| {result['case']} | {result['fixture_statements']:,} | {result['expected_count']:,} | "
                     f"{b:.3f} | {a:.3f} | {result['allocation_change_percent']:+.1f}% |")
    lines += ["", "## Adjacency engagement per evaluation", "",
              "These counters cover warmup and measurement in both forks, exclude initial setup diagnostics, "
              "and are divided by the corresponding evaluation count. They establish route engagement, "
              "not latency by themselves. Raw per-fork counts are retained in summary.json and the full logs.", "",
              "| Case | Lookup hits before → after | Kernel views before → after | Planner stats before → after |",
              "| --- | ---: | ---: | ---: |"]
    for result in results:
        b, a = (result[v]["counters_per_evaluation"] for v in ("before", "after"))
        fields = [f"{b[name]:g} → {a[name]:g}" for name in ("lookupHits", "kernelViews", "plannerStatsHits")]
        lines.append(f"| {result['case']} | " + " | ".join(fields) + " |")
    lines.append("")
    (args.output / "RESULTS.md").write_text("\n".join(lines))
    print(f"Validated {len(results)} pairs; wrote summary.json and RESULTS.md")


if __name__ == "__main__":
    main()
